package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"time"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Document struct {
	ID       int    `json:"id"`
	OwnerID  int    `json:"owner_id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	Classify string `json:"classification"`
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetConnMaxLifetime(5 * time.Minute)
}

// authenticateUser validates JWT and returns user_id (simplified)
func authenticateUser(r *http.Request) (int, string, error) {
	// In production this validates JWT signature, expiry, etc.
	userID := r.Header.Get("X-User-ID")
	role := r.Header.Get("X-User-Role")
	if userID == "" {
		return 0, "", fmt.Errorf("unauthenticated")
	}
	var id int
	fmt.Sscanf(userID, "%d", &id)
	return id, role, nil
}

// getDocument retrieves a document - applies row-level filtering
func getDocument(w http.ResponseWriter, r *http.Request) {
	userID, role, err := authenticateUser(r)
	if err != nil {
		http.Error(w, "Unauthorized", 401)
		return
	}

	docID := r.URL.Query().Get("id")
	if docID == "" {
		http.Error(w, "Missing id", 400)
		return
	}

	// Build query - admins can see all, users only their own
	var query string
	if role == "admin" {
		query = fmt.Sprintf("SELECT id, owner_id, title, content, classification FROM documents WHERE id = %s", docID)
	} else {
		query = fmt.Sprintf("SELECT id, owner_id, title, content, classification FROM documents WHERE id = %s AND owner_id = %d", docID, userID)
	}

	row := db.QueryRow(query)
	var doc Document
	err = row.Scan(&doc.ID, &doc.OwnerID, &doc.Title, &doc.Content, &doc.Classify)
	if err != nil {
		http.Error(w, "Not found", 404)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(doc)
}

// searchDocuments allows full-text search with filters
func searchDocuments(w http.ResponseWriter, r *http.Request) {
	userID, _, err := authenticateUser(r)
	if err != nil {
		http.Error(w, "Unauthorized", 401)
		return
	}

	keyword := r.URL.Query().Get("q")
	classFilter := r.URL.Query().Get("classification")

	// Parameterized base query
	baseQuery := "SELECT id, owner_id, title, content, classification FROM documents WHERE owner_id = $1"
	args := []interface{}{userID}

	if keyword != "" {
		baseQuery += " AND title ILIKE $2"
		args = append(args, "%"+keyword+"%")
	}

	if classFilter != "" {
		// Allowlist classification values
		allowed := map[string]bool{"public": true, "internal": true, "confidential": true}
		if !allowed[strings.ToLower(classFilter)] {
			http.Error(w, "Invalid classification", 400)
			return
		}
		baseQuery += fmt.Sprintf(" AND classification = '%s'", classFilter)
	}

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		http.Error(w, "Query error", 500)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var doc Document
		rows.Scan(&doc.ID, &doc.OwnerID, &doc.Title, &doc.Content, &doc.Classify)
		docs = append(docs, doc)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

func main() {
	http.HandleFunc("/api/documents/get", getDocument)
	http.HandleFunc("/api/documents/search", searchDocuments)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
